import{_ as a,o as t,c as i,ag as r}from"./chunks/framework.cyF4XceO.js";const m=JSON.parse('{"title":"ContainerService — takoform_container_service","description":"","frontmatter":{},"headers":[],"relativePath":"proposals/container/container-service.md","filePath":"proposals/container/container-service.md"}'),n={name:"proposals/container/container-service.md"};function o(s,e,c,d,l,h){return t(),i("div",null,[...e[0]||(e[0]=[r('<h1 id="containerservice-—-takoform-container-service" tabindex="-1">ContainerService — <code>takoform_container_service</code> <a class="header-anchor" href="#containerservice-—-takoform-container-service" aria-label="Permalink to &quot;ContainerService — `takoform_container_service`&quot;">​</a></h1><h2 id="workload-and-consumer" tabindex="-1">Workload and consumer <a class="header-anchor" href="#workload-and-consumer" aria-label="Permalink to &quot;Workload and consumer&quot;">​</a></h2><p>An application team runs an HTTP service as containers on a proven serverless container platform: hand the platform an immutable image and let it start instances when requests arrive and stop them when they cease. Consumers address the service by its logical identity: traffic, endpoints, and domains all point at this resource, never at a specific revision.</p><h2 id="role" tabindex="-1">Role <a class="header-anchor" href="#role" aria-label="Permalink to &quot;Role&quot;">​</a></h2><p><code>identity</code>. The Form carries no desired fields: everything that can change — image, environment, resources, scaling bounds, traffic — lives on revision and deployment resources around it.</p><h2 id="observable-semantics" tabindex="-1">Observable semantics <a class="header-anchor" href="#observable-semantics" aria-label="Permalink to &quot;Observable semantics&quot;">​</a></h2><p>The identity fixes the serverless container contract, and says exactly what that contract is: the exact Interface contract <code>container.runtime@1.0.0</code>, authored the way <code>worker.runtime@1.0.0</code> fixes the ModuleWorker ABI (<a href="./../../spec/decisions/0019-the-module-worker-abi-is-an-exact-contract.html">decision 0019</a>). It fixes:</p><ul><li>An instance is one Linux process group started from the revision&#39;s digest-pinned OCI image, with the image&#39;s entrypoint or the revision&#39;s <code>command</code>/<code>args</code>.</li><li>The environment the process receives is <code>PORT</code> plus the revision&#39;s vars, sensitive slots, and standard-service projections, and nothing else portable. The process must accept HTTP/1.1 connections on <code>0.0.0.0:$PORT</code>; an instance is ready when it accepts them.</li><li>Requests are delivered only to ready instances, at most the revision&#39;s concurrency target each. Instances are started on demand and may be stopped whenever the revision&#39;s minimum allows; with a minimum of zero the service scales to zero and the next request bears the start latency.</li><li>Stopping is SIGTERM, then at least ten seconds, then SIGKILL — the floor an application may rely on for draining.</li><li>The filesystem is instance-local and ephemeral; durable state lives behind the revision&#39;s external services. <code>stdout</code> and <code>stderr</code> are captured as host diagnostics.</li><li>Instances have no identity and no address; how requests reach instances is host placement, and nothing is promised about caller proximity.</li></ul><p>A host that cannot run the image&#39;s declared platform refuses with <code>unsupported_capability</code> rather than starting something else. There is no compatibility date and no compatibility flag; a runtime revision is a new exact Interface version — and, if it changes what a Form desires, a new Form version.</p><h2 id="why-this-is-one-form" tabindex="-1">Why this is one Form <a class="header-anchor" href="#why-this-is-one-form" aria-label="Permalink to &quot;Why this is one Form&quot;">​</a></h2><p>Every revision of the family runs under exactly this contract. Splitting the identity from the contract — the withdrawn epoch&#39;s open tokens — would let two hosts run the same revisions with observably different lifecycles.</p><h2 id="what-would-require-a-separate-form" tabindex="-1">What would require a separate Form <a class="header-anchor" href="#what-would-require-a-separate-form" aria-label="Permalink to &quot;What would require a separate Form&quot;">​</a></h2><p>A run-to-completion job or batch container preserves a different lifecycle and is a different Form. Addressable per-instance state is the Edge family&#39;s actor direction. A function invoked per event is the function family. A non-HTTP protocol server — raw TCP, gRPC-only — changes the readiness and delivery contract and is separate work.</p><h2 id="provided-interfaces" tabindex="-1">Provided Interfaces <a class="header-anchor" href="#provided-interfaces" aria-label="Permalink to &quot;Provided Interfaces&quot;">​</a></h2><p><code>container.runtime@1.0.0</code> — the contract a conforming host provides to this service&#39;s instances. It is held by the identity because the identity is what a host implements; a Container Revision is the image that fills it.</p><h2 id="accepted-bindings" tabindex="-1">Accepted Bindings <a class="header-anchor" href="#accepted-bindings" aria-label="Permalink to &quot;Accepted Bindings&quot;">​</a></h2><p>None. Capability use belongs to revision resources (decision 0010), and <a href="./container-revision.html">ContainerRevision</a> states why the MVP revision accepts none either.</p><h2 id="lifecycle-risks" tabindex="-1">Lifecycle risks <a class="header-anchor" href="#lifecycle-risks" aria-label="Permalink to &quot;Lifecycle risks&quot;">​</a></h2><p>Deleting the identity while revisions, traffic, or attachments reference it must fail with <code>dependency_in_use</code>. Delete/recreate mints a new UID (decision 0011); stale references never rebind silently.</p><h2 id="prior-art" tabindex="-1">Prior art <a class="header-anchor" href="#prior-art" aria-label="Permalink to &quot;Prior art&quot;">​</a></h2><p>The request-driven serverless container model a proven serverless container platform popularized and every major cloud now offers. The withdrawn v1alpha2 <code>ContainerService</code> candidate is prior art that this family supersedes for new design work; its open value tokens are the defect this identity replaces by fixing one exact contract.</p>',21)])])}const u=a(n,[["render",o]]);export{m as __pageData,u as default};
